 final ExecutorService worker=Executors.newSingleThreadExecutor();TextView status;SurfaceView preview;volatile boolean closed;boolean busy;ScrollView controls;boolean connecting;boolean projectionMode,videoReady;TextView connectionHint;View videoBlank;TextView operationStatus;LinearLayout actionRow;int actionCount;
 public void onCreate(Bundle b){super.onCreate(b);active=this;getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(20),dp(18),dp(20),dp(18));
  TextView title=new TextView(this);title.setText("DiPlay");title.setTextSize(26);title.setTextColor(0xfff1f5f9);root.addView(title);
  TextView subtitle=new TextView(this);String version="";try{version=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception ignored){}subtitle.setText("有线 CarPlay · "+version);subtitle.setTextSize(12);subtitle.setTextColor(0xff94a3b8);root.addView(subtitle);
  status=new TextView(this);status.setTextSize(16);status.setTextColor(0xffe2e8f0);status.setPadding(0,dp(18),0,dp(12));status.setText("等待 iPhone 插入\n旧车机每次开机首次连接需确认 VPN；USB 授权请选择 DiPlay。\n连接后按返回键显示或收起面板。");root.addView(status);
  operationStatus=new TextView(this);operationStatus.setTextSize(14);operationStatus.setTextColor(0xff7dd3fc);operationStatus.setPadding(0,0,0,dp(8));operationStatus.setVisibility(View.GONE);root.addView(operationStatus);
  button(root,"连接",new Runnable(){public void run(){AutoUsbService.resume(MainActivity.this);connectPending=true;scheduleConnection(0);}});
  button(root,"停止",new Runnable(){public void run(){stopConnection();}});
  preview=new ProjectionSurface(this);preview.getHolder().setFixedSize(ProjectionConfig.WIDTH,ProjectionConfig.HEIGHT);controls=new ScrollView(this);controls.addView(root);FrameLayout outer=new FrameLayout(this);outer.setBackgroundColor(0xff000000);outer.addView(preview,new FrameLayout.LayoutParams(-1,-1,Gravity.CENTER));videoBlank=new View(this);videoBlank.setBackgroundColor(0xff000000);videoBlank.setClickable(false);outer.addView(videoBlank,new FrameLayout.LayoutParams(-1,-1));
  connectionHint=new TextView(this);connectionHint.setTextSize(18);connectionHint.setTextColor(0xffffffff);connectionHint.setBackgroundColor(0xcc111827);connectionHint.setPadding(12,8,12,8);connectionHint.setVisibility(View.GONE);outer.addView(connectionHint,new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM));
  controls.setBackgroundColor(0xf5111827);controls.setFillViewport(true);int panelWidth=Math.min(dp(360),Math.max(dp(280),getResources().getDisplayMetrics().widthPixels*43/100));outer.addView(controls,new FrameLayout.LayoutParams(panelWidth,-1,Gravity.LEFT));setContentView(outer);registerReceiver(portStatus,new IntentFilter("local.headunit.diplay.STATUS"));preview.setOnTouchListener(new View.OnTouchListener(){public boolean onTouch(View v,MotionEvent e){WiredService.touch(e.getActionMasked(),e.getX()/Math.max(1,preview.getWidth()),e.getY()/Math.max(1,preview.getHeight()));return true;}});
  preview.getHolder().addCallback(new SurfaceHolder.Callback(){public void surfaceCreated(SurfaceHolder h){WiredService.attachSurface(MainActivity.this,h.getSurface());if(connectPending)scheduleConnection(0);}public void surfaceChanged(SurfaceHolder h,int format,int width,int height){}public void surfaceDestroyed(SurfaceHolder h){WiredService.detachSurface(MainActivity.this);lifecycle("surface_destroyed");}});
  AutoUsbService.start(this);if((getIntent().getBooleanExtra("auto_connect",false)||UsbManager.ACTION_USB_DEVICE_ATTACHED.equals(getIntent().getAction()))&&AutoUsbService.canConnect(this))connectPending=true;

 }
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 Drawable buttonBackground(boolean primary){StateListDrawable states=new StateListDrawable();GradientDrawable pressed=new GradientDrawable();pressed.setColor(primary?0xff0284c7:0xff334155);pressed.setCornerRadius(dp(10));GradientDrawable normal=new GradientDrawable();normal.setColor(primary?0xff0369a1:0xff1e293b);normal.setCornerRadius(dp(10));normal.setStroke(dp(1),primary?0xff38bdf8:0xff475569);states.addState(new int[]{android.R.attr.state_pressed},pressed);states.addState(new int[]{},normal);return states;}
 boolean actionAllowedWhileConnected(String label){return !connecting||label.equals("停止");}
 void button(LinearLayout r,final String label,final Runnable action){Button b=new Button(this);b.setText(label);b.setTextSize(17);b.setTextColor(0xfff1f5f9);b.setBackgroundDrawable(buttonBackground(label.equals("连接")));b.setPadding(dp(8),0,dp(8),0);b.setOnClickListener(new View.OnClickListener(){public void onClick(View v){if(label.equals("停止")){action.run();return;}if(!actionAllowedWhileConnected(label)){showOperation("请先停止连接，再操作。");return;}if(busy||maintenance){showOperation("正在处理上一项操作，请稍候。");return;}action.run();}});if(actionCount%2==0){actionRow=new LinearLayout(this);actionRow.setOrientation(0);LinearLayout.LayoutParams row=new LinearLayout.LayoutParams(-1,-2);row.topMargin=dp(10);r.addView(actionRow,row);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(56),1);if(actionCount%2==0)lp.rightMargin=dp(5);else lp.leftMargin=dp(5);actionRow.addView(b,lp);actionCount++;}
 void stopConnection(){requestStartedAt=0;vpnWaitMs=0;AutoUsbService.pause(this);connectPending=false;permissionPending=false;uiHandler.removeCallbacks(tryConnection);connectionId="stopped-"+UUID.randomUUID();WiredService.stop(this);connecting=false;videoReady=false;setProjectionMode(false);show("已停止。本次插入不再自动重连；重新插拔或点击连接可恢复。");}
 void scheduleConnection(long delay){uiHandler.removeCallbacks(tryConnection);if(!closed)uiHandler.postDelayed(tryConnection,delay);}
 void showOperation(String s){if(!closed&&operationStatus!=null){operationStatus.setText(s);operationStatus.setVisibility(View.VISIBLE);}}
 void show(String s){if(!closed){status.setText(s);if(connectionHint!=null)connectionHint.setText(s+"\n按返回键显示连接面板");}}
 void refreshVideoBlank(){if(videoBlank!=null)videoBlank.setVisibility(connecting&&videoReady?View.GONE:View.VISIBLE);}
 void setProjectionMode(boolean enabled){projectionMode=enabled;refreshVideoBlank();controls.setVisibility(enabled?View.GONE:View.VISIBLE);connectionHint.setVisibility(enabled&&connecting&&!videoReady?View.VISIBLE:View.GONE);if(enabled)getWindow().addFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);else getWindow().clearFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN);preview.post(new Runnable(){public void run(){if(!closed)try{record(MainActivity.this,"projection_layout",new JSONObject().put("projectionMode",projectionMode).put("panelVisible",controls.getVisibility()==View.VISIBLE).put("surfaceWidth",preview.getWidth()).put("surfaceHeight",preview.getHeight()).put("windowWidth",preview.getRootView().getWidth()).put("windowHeight",preview.getRootView().getHeight()));}catch(Exception ignored){}}});}
 static final class ProjectionSurface extends SurfaceView {
  ProjectionSurface(Context c){super(c);}
  protected void onMeasure(int widthSpec,int heightSpec){int w=View.MeasureSpec.getSize(widthSpec),h=View.MeasureSpec.getSize(heightSpec);int width=Math.min(w,h*ProjectionConfig.WIDTH/ProjectionConfig.HEIGHT);setMeasuredDimension(width,width*ProjectionConfig.HEIGHT/ProjectionConfig.WIDTH);}
 }
 static void record(Context c,String name,JSONObject details)throws Exception{DiagnosticLog.record(c,name,details);}

 final Runnable tryConnection=new Runnable(){public void run(){if(closed||!resumed||!connectPending||permissionPending)return;if(busy||maintenance){scheduleConnection(500);return;}if(WiredService.isBusy()){scheduleConnection(500);return;}if(!preview.getHolder().getSurface().isValid()){scheduleConnection(100);return;}connectPending=false;requestConnection();}};
 void requestConnection(){if(connecting||permissionPending)return;if(!resumed||!preview.getHolder().getSurface().isValid()){connectPending=true;scheduleConnection(100);return;}if(WiredService.isBusy()){connectPending=true;scheduleConnection(500);return;}if(requestStartedAt==0)requestStartedAt=SystemClock.elapsedRealtime();Intent permission=VpnService.prepare(this);try{record(this,"VPN_PERMISSION_CHECK",new JSONObject().put("required",permission!=null).put("uptimeMs",SystemClock.elapsedRealtime()));}catch(Exception ignored){}if(permission!=null){vpnPromptAt=SystemClock.elapsedRealtime();try{record(this,"VPN_PERMISSION_PROMPT",new JSONObject().put("uptimeMs",vpnPromptAt));}catch(Exception ignored){}permissionPending=true;show("此旧系统每次开机首次连接需确认 VPN，用于 iPhone USB 网络。照片/视频访问不是 CarPlay 授权。请停车后操作。");startActivityForResult(permission,11);}else connectPort();}
 protected void onNewIntent(Intent i){super.onNewIntent(i);setIntent(i);if((i.getBooleanExtra("auto_connect",false)||UsbManager.ACTION_USB_DEVICE_ATTACHED.equals(i.getAction()))&&AutoUsbService.canConnect(this)&&!connecting){connectPending=true;scheduleConnection(0);}}
 protected void onResume(){super.onResume();resumed=true;restoreConnection();refreshVideoBlank();lifecycle("resume");if(connectPending)scheduleConnection(0);}
 protected void onPause(){resumed=false;WiredService.detachSurface(this);uiHandler.removeCallbacks(tryConnection);super.onPause();}
 protected void onStop(){lifecycle("background");super.onStop();}
 public static boolean wheelProbeActive(){return false;}
 public boolean dispatchKeyEvent(KeyEvent event){if(WiredService.consumeWheelDuplicate(event.getKeyCode()))return true;return super.dispatchKeyEvent(event);}
 void lifecycle(String event){try{record(this,"PROJECTION_UI",new JSONObject().put("event",event).put("connection",connectionId).put("surfaceValid",preview.getHolder().getSurface().isValid()));}catch(Exception ignored){}}
 void restoreConnection(){String id=WiredService.currentConnectionId();if(id.length()>0){boolean restored=!connecting||!id.equals(connectionId);connectionId=id;connecting=true;connectPending=false;videoReady=WiredService.isVideoReady();if(preview.getHolder().getSurface().isValid())WiredService.attachSurface(this,preview.getHolder().getSurface());if(restored){show(videoReady?"CarPlay 会话已恢复显示":"正在建立 CarPlay 连接");setProjectionMode(true);}}else if(connecting){connecting=false;videoReady=false;setProjectionMode(false);}}

 void connectPort(){if(connecting){show("正在连接，请先停止再重试。");return;}if(requestStartedAt==0)requestStartedAt=SystemClock.elapsedRealtime();if(!preview.getHolder().getSurface().isValid()){show("画面尚未就绪");return;}connecting=true;videoReady=false;show("正在连接iPhone，请在手机和车机上确认授权");setProjectionMode(true);WiredService.attachSurface(this,preview.getHolder().getSurface());try{connectionId=UUID.randomUUID().toString();startService(new Intent(this,WiredService.class).putExtra("connection_id",connectionId).putExtra("request_started_at",requestStartedAt).putExtra("vpn_wait_ms",vpnWaitMs));}catch(RuntimeException e){requestStartedAt=0;vpnWaitMs=0;connecting=false;setProjectionMode(false);show("无法启动连接："+e.getClass().getSimpleName());}}
 final BroadcastReceiver portStatus=new BroadcastReceiver(){public void onReceive(Context c,Intent i){String id=i.getStringExtra("connection_id");if(id!=null&&!id.equals(connectionId))return;show(i.getStringExtra("message"));String stage=i.getStringExtra("stage");if("VIDEO_READY".equals(stage)){videoReady=true;refreshVideoBlank();connectionHint.setVisibility(View.GONE);}if("DISCONNECTED".equals(stage)||"STOPPED".equals(stage)||"FAILED".equals(stage)){requestStartedAt=0;vpnWaitMs=0;connecting=false;videoReady=false;setProjectionMode(false);}}};
 public void onBackPressed(){if(projectionMode){setProjectionMode(false);return;}if(connecting){setProjectionMode(true);return;}super.onBackPressed();}
 protected void onActivityResult(int r,int code,Intent data){super.onActivityResult(r,code,data);if(r==20||r==21){maintenance=false;AutoUsbService.endMaintenance(this);return;}if(r==11){if(!permissionPending)return;permissionPending=false;vpnWaitMs+=Math.max(0,SystemClock.elapsedRealtime()-vpnPromptAt);try{record(this,"VPN_PERMISSION_RESULT",new JSONObject().put("granted",code==RESULT_OK).put("waitMs",vpnWaitMs));}catch(Exception ignored){}if(code==RESULT_OK){connectPending=true;scheduleConnection(0);}else{requestStartedAt=0;vpnWaitMs=0;connectPending=false;AutoUsbService.pause(this);show("未授权VPN，本次自动连接已暂停。");}}}

 public void onDestroy(){closed=true;connectPending=false;uiHandler.removeCallbacksAndMessages(null);WiredService.detachSurface(this);if(active==this)active=null;unregisterReceiver(portStatus);worker.shutdown();super.onDestroy();}
